export type TaskStatus = "todo" | "in_progress" | "in_review" | "done";

/** One work session. `end` is null while the timer is still running. */
export interface TimeEntry {
  id: string;
  userId: string;
  start: string; // ISO 8601 UTC, e.g. "2025-01-15T09:30:00Z"
  end: string | null;
  note?: string;
}

export type CustomPropertyValue = string | number | boolean | string[] | null;

export interface Task {
  id: string;
  title: string;
  status: TaskStatus;
  assigneeIds: string[];
  timeEntries: TimeEntry[];
  /** Keyed by property definition ID, so renaming a property doesn't break data. */
  customProperties: Record<string, CustomPropertyValue>;
  createdAt: string;
  updatedAt: string;
}
```

**Design notes**

- **Intervals instead of minutes:** Each `TimeEntry` stores only `start` and `end`. Duration is derived (`end - start`), so it can't drift out of sync, and you can still query by date range, detect overlaps, or build timesheets and calendar views.
- **Running timers:** `end: null` means a session is in progress, so you don't need a separate `isRunning` flag.
- **ISO strings instead of `Date`:** They survive JSON serialization and the Next.js server/client boundary (Server Components, API routes) without conversion surprises.
- **Dynamic custom fields:** `customProperties` is a flexible map of values. Keep a separate `PropertyDefinition` type (name, type, select options) at the project or workspace level to validate and render these fields, much like Notion database columns.

